use engine_native::{Engine,GameCommand,GameAction,CommandOutcome,ChoiceOption,Phase,EventView,LogEvent};
use engine_native::archive::{encode_archive,decode_archive};
use engine_native::ai::BoundedPlanner;
use engine_native::view::{SeatPolicy,PolicyInput};
fn submit(e:&mut Engine,actor:u8,action:GameAction)->CommandOutcome {let d=e.save().last_dedup+1;e.submit(GameCommand{actor,action,expected_revision:e.revision(),dedup_id:d})}
fn answer(e:&mut Engine,s:Vec<ChoiceOption>)->CommandOutcome {let c=e.open_choice().unwrap().clone();submit(e,c.observer,GameAction::Answer{choice_id:c.id,selection:s})}
fn play_setup(seed:u64)->Engine {let mut e=Engine::new(seed,3);for _ in 0..12 {if e.turn().phase==Phase::Play {break}let p=e.turn().current;assert!(!matches!(submit(&mut e,p,GameAction::NextPhase),CommandOutcome::Rejected(_)));}for p in 0..3{e.debug_clear_hand(p)}e}
struct Passive;impl SeatPolicy for Passive{fn act(&mut self,_:&PolicyInput)->Option<GameAction>{None}}
fn main(){
let mut a=Engine::new(443,4);let token=a.issue_token(0);let mut b=Engine::new(443,4);assert_ne!(token,b.issue_token(0));
let out=b.submit_authed(token,GameCommand{actor:0,expected_revision:b.revision(),dedup_id:1,action:GameAction::NextPhase});assert!(matches!(out,CommandOutcome::Rejected(_)));
let snap=a.save();let mut restored=Engine::restore(&snap).unwrap();let fresh=restored.issue_token(0);assert_ne!(token,fresh);
let cmd=GameCommand{actor:0,expected_revision:restored.revision(),dedup_id:1,action:GameAction::NextPhase};assert!(matches!(restored.submit_authed(token,cmd.clone()),CommandOutcome::Rejected(_)));assert!(!matches!(restored.submit_authed(fresh,cmd),CommandOutcome::Rejected(_)));println!("FIXED_AUTH: cross-instance/old token rejected; fresh restored token accepted");
let orig=encode_archive(&snap);let mut bad=orig.clone();bad[6..14].copy_from_slice(&999u64.to_le_bytes());assert!(decode_archive(&bad).is_err());let mut bad=orig.clone();bad[14..22].copy_from_slice(&u64::MAX.to_le_bytes());assert!(std::panic::catch_unwind(||decode_archive(&bad)).unwrap().is_err());println!("FIXED_ARCHIVE: mismatched header and overflowing length return Err");
let mut bad=snap.clone();bad.core.players[0].general_slots=[Some(u16::MAX),None];bad.core.players[0].revealed_generals=[true,false];assert!(Engine::restore(&bad).is_err());let mut bad=snap.clone();bad.core.discard.push(bad.core.players[0].hand[0]);assert!(Engine::restore(&bad).is_err());println!("FIXED_SNAPSHOT: bad general id and duplicated zone card rejected");
let mut bad=snap.clone();let removed=bad.core.players[0].hand.pop().unwrap();assert!(Engine::restore(&bad).is_ok());println!("OPEN_MISSING_CARD: removed Card({removed}) from sole owning zone; restore accepted");
let mut e=Engine::new(901,3);e.debug_grant(0,"观星");for p in 0..3{e.debug_clear_hand(p)}let mut checked=false;
for _ in 0..128{let p=e.turn().current;match submit(&mut e,p,GameAction::NextPhase){CommandOutcome::Pending{..}=>{answer(&mut e,vec![ChoiceOption::Confirm]);let c=e.open_choice().unwrap().clone();assert_eq!(c.spec.prompt,"guanxing_arrange");let card=c.spec.options.iter().find(|x|matches!(x,ChoiceOption::Card(_))).copied().unwrap();answer(&mut e,vec![card]);let ev=e.ai_session(1).events();assert!(!ev.iter().any(|x|matches!(x,EventView::Public(LogEvent::ChoiceAnswered{id,..}) if *id==c.id)));assert!(ev.iter().any(|x|matches!(x,EventView::ChoiceAnsweredHidden{id} if *id==c.id)));checked=true;break},CommandOutcome::Accepted{..}=>{},x=>panic!("{x:?}")}}assert!(checked);println!("FIXED_PRIVATE_ANSWER: other seat sees ChoiceAnsweredHidden");
let mut e=play_setup(2004);e.debug_grant(1,"流离");e.debug_place(1,"tao");let sha=e.debug_place(0,"sha");submit(&mut e,0,GameAction::PlayCard{card:sha,targets:vec![1]});assert_eq!(e.open_choice().unwrap().spec.prompt,"liuli_transfer");let mut back=Engine::restore(&e.save()).unwrap();assert_eq!(e.state_hash(),back.state_hash());let direct=answer(&mut e,vec![ChoiceOption::Player(2)]);let resumed=answer(&mut back,vec![ChoiceOption::Player(2)]);assert_eq!(e.debug_hp(2),3);assert_eq!(back.debug_hp(2),4);assert_ne!(e.state_hash(),back.state_hash());println!("OPEN_LIULI_RESUME: direct={direct:?} hp2={} restored={resumed:?} hp2={}; identical saved hash diverges on same answer",e.debug_hp(2),back.debug_hp(2));
let mut e=play_setup(2201);e.debug_grant(1,"护驾");let shan=e.debug_place(0,"shan");let sha=e.debug_place(0,"sha");submit(&mut e,0,GameAction::PlayCard{card:sha,targets:vec![1]});let c=e.ai_session(1).choice().unwrap();assert!(e.open_choice().unwrap().spec.options.contains(&ChoiceOption::Card(shan)));answer(&mut e,vec![ChoiceOption::Card(shan)]);assert!(!e.debug_hand(0).contains(&shan));println!("OPEN_HUJIA_PRIVATE_CARD: defender view={c:?}; defender consumes attacker's private Shan without owner choice");
let mut e=Engine::new(2301,3);assert!(!matches!(e.submit(GameCommand{actor:0,expected_revision:e.revision(),dedup_id:1_000_000,action:GameAction::NextPhase}),CommandOutcome::Rejected(_)));let mut e=Engine::restore(&e.save()).unwrap();let out=e.run_policy(0,&mut Passive);assert!(matches!(out,CommandOutcome::Rejected(engine_native::RejectReason::DuplicateCommand)));let plan=e.plan_action(0,&BoundedPlanner::new(64));let out2=e.apply_plan(&plan).unwrap();assert!(matches!(out2,CommandOutcome::Rejected(engine_native::RejectReason::DuplicateCommand)));println!("OPEN_AI_DEDUP: after accepted dedup=1000000 and restore, run_policy={out:?} apply_plan={out2:?}");
let mut a=play_setup(2302);a.debug_place(0,"sha");a.debug_place(1,"shan");a.debug_place(2,"sha");let mut s=a.save();let one=s.core.players[1].hand[0];let two=s.core.players[2].hand[0];s.core.players[1].hand[0]=two;s.core.players[2].hand[0]=one;let b=Engine::restore(&s).unwrap();let a=Engine::restore(&a.save()).unwrap();assert_eq!(a.ai_session(0).view(),b.ai_session(0).view());assert_eq!(a.ai_session(0).input().own_hand_kinds,b.ai_session(0).input().own_hand_kinds);assert_eq!(a.ai_session(0).events(),b.ai_session(0).events());let pa=a.plan_action(0,&BoundedPlanner::new(64));let pb=b.plan_action(0,&BoundedPlanner::new(64));assert_ne!(format!("{:?}",pa.action),format!("{:?}",pb.action));println!("OPEN_AI_HIDDEN_STATE: equal seat view/events/hand metadata but hidden Shan swap changes plan: {:?} -> {:?}",pa.action,pb.action);
let mut e=play_setup(2303);let shan=e.debug_place(1,"shan");let sha=e.debug_place(0,"sha");submit(&mut e,0,GameAction::PlayCard{card:sha,targets:vec![1]});let c=e.open_choice().unwrap().clone();let plan=e.plan_action(1,&BoundedPlanner::new(64));assert_eq!(plan.nodes_used,2);assert!(matches!(plan.action,GameAction::Answer{selection,..} if selection==vec![ChoiceOption::Pass]));let mut defend=Engine::restore(&e.save()).unwrap();answer(&mut defend,vec![ChoiceOption::Card(shan)]);assert_eq!(defend.debug_hp(1),4);println!("OPEN_AI_OPTIONS: options={:?} max={} candidate nodes=2 (Pass + invalid NextPhase); legal Shan never evaluated",c.spec.options,c.spec.max);
let cat=Engine::new(1,3).catalog().clone();let gs=engine_native::content::standard::STANDARD_GENERALS;let ordinary=gs.iter().filter(|g|!g.0.starts_with("样例")).count();assert_eq!(ordinary,25);for (name,skill) in [("曹操","护驾"),("貂蝉","离间"),("大乔","流离"),("周瑜","反间"),("孙尚香","结姻"),("华佗","急救")] {let g=gs.iter().find(|g|g.0==name).unwrap();assert!(cat.skill_by_name(skill).is_some());assert!(!g.2.contains(&skill));println!("OPEN_GENERAL_WIRING: {name} exists but general_skills omits {skill}");}println!("CATALOG_COUNT ordinary={ordinary} samples={}",gs.len()-ordinary);
println!("REVIEW13_PROBES_COMPLETE ruleset={}",snap.ruleset_version);
}
